import React, { useState } from 'react';
import './App.css';

function App() {
  const [report, setReport] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleScan = async () => {
    if (!report) return alert("Please paste a report first!");

    setLoading(true);
    try {
      const res = await fetch('http://127.0.0.1:8000/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: report }),
      });

      const data = await res.json();

      // If the backend sent a string (common with LLMs), we parse it. 
      // If it's already an object, we use it directly.
      const finalData = typeof data === 'string' 
        ? JSON.parse(data.replace(/```json|```/g, '')) 
        : data;

      setResult(finalData);
    } catch (err) {
      console.error("Analysis Error:", err);
      alert("Error: Is your Python backend running on port 8000?");
    }
    setLoading(false);
  };

  return (
    <div className="container">
      <h1>🎻 Luthier-AI Auction Scanner</h1>
      <p>Expert analysis for Tarisio condition reports</p>

      <textarea 
        placeholder="Paste Tarisio condition report here (e.g., 'Soundpost crack in the back...')" 
        value={report}
        onChange={(e) => setReport(e.target.value)}
      />

      <div className="actions">
        <button onClick={handleScan} disabled={loading}>
          {loading ? 'Analyzing with Gemini...' : 'Scan Report'}
        </button>
      </div>

      {result && (
        <div className="results">
          <h2>Risk Assessment: {result.risk_score}/10</h2>

          <h3>Structural Red Flags:</h3>
          {result.red_flags && result.red_flags.length > 0 ? (
            <ul>
              {result.red_flags.map((flag, i) => (
                <li key={i} className="flag">⚠️ {flag}</li>
              ))}
            </ul>
          ) : (
            <p>No major structural red flags detected.</p>
          )}

          <h3>Professional Summary:</h3>
          <p className="summary-text">{result.summary}</p>
        </div>
      )}
    </div>
  );
}

export default App;
